SELECT /*LGVPAYP0001.retrieveCalculationSetList*/ pacs.payroll_calculation_set_id as calculation_set_id , pacs.payroll_calculation_set_name as calculation_set_name , ccml.common_code_name as payroll_type , pacs.creation_date , ( SELECT COUNT(*) FROM tb_pay_calc_set_target_per_n a WHERE a.payroll_calculation_set_id = pacs.payroll_calculation_set_id) as employee_count , pacs.resignation_flag FROM tb_pay_calc_set_n pacs , lgcom_common_code_multi_lang_c ccml WHERE ccml.code_type_code= 'LGVHR_PAY_RUN_TYPE' AND ccml.common_code = pacs.payroll_type_code AND ccml.language_code = #{USER_SESSION.languageCode}
AND pacs.payroll_calculation_set_name LIKE '%' || #{calculationSetName} ||'%'
AND pacs.payroll_type_code = #{payrollType}
AND pacs.resignation_flag = #{resignationFlag}
ORDER BY pacs.payroll_calculation_set_name
